html,body{margin:0;height:100%;background:#1e293b;font-family:'Open Sans',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#e2e8f0;}
*{box-sizing:border-box;}
.card{padding:24px 28px;height:calc(var(--appsmith-ui-height)*1px);display:flex;flex-direction:column;}
.mh{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;}
.mh h3{margin:0;font-size:22px;font-weight:800;color:#f1f5f9;}
.mh .x{cursor:pointer;color:#94a3b8;font-size:22px;line-height:1;}
.mh .x:hover{color:#e2e8f0;}
p.desc{color:#cbd5e1;font-size:14px;line-height:1.5;margin:0 0 22px;}
.row{display:flex;gap:20px;}
.fld{flex:1;}
.fld label{display:block;font-size:14px;color:#e2e8f0;font-weight:600;margin-bottom:8px;}
.fld label .req{color:#f87171;}
.fld select{width:100%;background:#0f172a;color:#e2e8f0;border:1px solid #334155;border-radius:6px;padding:10px 12px;font-size:14px;height:42px;outline:none;cursor:pointer;}
.fld select:focus{border-color:#3b82f6;}
.fld select option:disabled{color:#475569;}
.acts{display:flex;gap:14px;margin-top:auto;padding-top:32px;}
.btn{padding:11px 26px;border-radius:8px;font-size:15px;font-weight:600;cursor:pointer;border:1px solid #334155;}
.btn.cancel{background:transparent;color:#e2e8f0;}
.btn.cancel:hover{background:#0f172a;}
.btn.primary{background:#2563eb;color:#fff;border-color:#2563eb;}
.btn.primary:hover{background:#1d4ed8;}
::-webkit-scrollbar{width:10px;height:10px;background:#1e293b;} ::-webkit-scrollbar-thumb{background:#334155;border-radius:4px;border:2px solid #1e293b;}

