var MONTHS=["January","February","March","April","May","June","July","August","September","October","November","December"];
var selYear="";

function existing(){
  var rows=(appsmith.model&&appsmith.model.rows)||[];
  var map={};
  rows.forEach(function(r){
    var s=String(r._sort||"").slice(0,7);
    var p=s.split("-");
    if(p.length>=2){ var y=p[0], mi=parseInt(p[1],10); if(!map[y])map[y]={}; map[y][mi]=true; }
  });
  return map;
}

function render(){
  var ex=existing();
  var nowY=(new Date()).getFullYear();
  var years=[]; for(var y=nowY+1;y>=nowY-6;y--) years.push(String(y));
  var yopts='<option value="">Choose year</option>'+years.map(function(y){
    var full=false; if(ex[y]){ var c=0; for(var i=1;i<=12;i++) if(ex[y][i]) c++; full=(c>=12); }
    return '<option value="'+y+'"'+(selYear===y?' selected':'')+(full?' disabled':'')+'>'+y+(full?' (added)':'')+'</option>';
  }).join('');
  var mopts='<option value="">Choose months</option>'+MONTHS.map(function(m,i){
    var mi=i+1; var dis=selYear&&ex[selYear]&&ex[selYear][mi];
    return '<option value="'+mi+'"'+(dis?' disabled':'')+'>'+m+(dis?' (added)':'')+'</option>';
  }).join('');
  var root=document.getElementById("root"); if(!root) return;
  root.innerHTML='<div class="card">'
    +'<div class="mh"><h3>Add Year/Months</h3><span class="x" id="x">✕</span></div>'
    +'<p class="desc">Years and Months that are already part of your list will appear as disabled in the below dropdowns.</p>'
    +'<div class="row"><div class="fld"><label>Year <span class="req">*</span></label><select id="ysel">'+yopts+'</select></div>'
    +'<div class="fld"><label>Months <span class="req">*</span></label><select id="msel">'+mopts+'</select></div></div>'
    +'<div class="acts"><button class="btn cancel" id="cancel">Cancel</button><button class="btn primary" id="add">Add</button></div>'
  +'</div>';
  var y=document.getElementById("ysel"); if(y) y.onchange=function(e){ selYear=e.target.value; render(); };
  var x=document.getElementById("x"); if(x) x.onclick=function(){ appsmith.triggerEvent("onClose"); };
  var c=document.getElementById("cancel"); if(c) c.onclick=function(){ appsmith.triggerEvent("onClose"); };
  var a=document.getElementById("add"); if(a) a.onclick=function(){ appsmith.triggerEvent("onAdd"); };
}

appsmith.onReady(function(){ render(); appsmith.onModelChange(render); });

